import{_ as t,o,c as i,a4 as r}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse(`{"title":"ADR-0064 — Page d'accueil d'un site et descripteur public d'un site par son hôte","description":"Extrait de docs/adr/0064-page-d-accueil-et-descripteur-de-site.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0064 — Page d'accueil d'un site et descripteur public d'un site par son hôte","description":"Extrait de docs/adr/0064-page-d-accueil-et-descripteur-de-site.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0064-page-d-accueil-et-descripteur-de-site.md","filePath":"developpeurs/adr/0064-page-d-accueil-et-descripteur-de-site.md"}`),d={name:"developpeurs/adr/0064-page-d-accueil-et-descripteur-de-site.md"};function a(s,e,n,c,l,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0064--page-daccueil-dun-site-et-descripteur-public-dun-site-par-son-hôte" tabindex="-1">ADR-0064 — Page d&#39;accueil d&#39;un site et descripteur public d&#39;un site par son hôte <a class="header-anchor" href="#adr-0064--page-daccueil-dun-site-et-descripteur-public-dun-site-par-son-hôte" aria-label="Permalink to &quot;ADR-0064 — Page d&#39;accueil d&#39;un site et descripteur public d&#39;un site par son hôte {#adr-0064--page-daccueil-dun-site-et-descripteur-public-dun-site-par-son-hôte}&quot;">​</a></h1><p><strong>Date :</strong> 1er octobre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> lot 10 (front de démarrage, <a href="/teuthis-cms-distribution/developpeurs/adr/0047-front-de-demarrage-optionnel">ADR-0047</a>) : un front client de la seule API publique ne savait ni servir la racine <code>/</code> de son site, ni trouver son site à partir de l&#39;en-tête <code>Host</code><strong>Complète :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0034-adresses-publiques">ADR-0034</a> (résolution des adresses), <a href="/teuthis-cms-distribution/developpeurs/adr/0035-plan-de-site-flux-et-robots">ADR-0035</a> (plan de site)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p><code>GET /api/v1/public/resolve?path=/</code> répondait 404 : aucune colonne ne désignait la page d&#39;accueil d&#39;un site. Un front public n&#39;avait donc aucun moyen de servir la racine sans coder en dur une page.</p><p>Le front de démarrage (ADR-0047) ne connaît que l&#39;en-tête <code>Host</code> de la requête qu&#39;il sert. Or les listes, la recherche, l&#39;identité visuelle, les formulaires et le bandeau de cookies demandent <code>organization_id</code> et <code>site_id</code>. Aucune route publique ne les donnait à partir d&#39;un nom d&#39;hôte.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong>Un réglage « page d&#39;accueil » par site</strong>, choisi dans le back-office (décision du Product Owner). Colonne nullable <code>sites.home_page_id</code> (migration 0047), clé étrangère vers <code>pages.id</code>, <code>ON DELETE SET NULL</code> : supprimer la page efface le réglage et la racine retombe sur un 404, sans rien bloquer.</li><li><strong>La page doit être du site.</strong> Aucune contrainte en base ne l&#39;impose ; <code>PUT /api/v1/sites/{id}/home-page</code> (<code>multisite.manage</code>, comme le domaine et l&#39;indexation) refuse une page inconnue ou d&#39;un autre site par une erreur <strong>422 sur <code>home_page_id</code></strong> (<code>FormValidationError</code>), le même message dans les deux cas. À la lecture, la résolution vérifie de nouveau l&#39;appartenance. <code>GET /api/v1/sites/{id}/home-page</code> rend le réglage et les pages du site avec leur chemin, bornées (2 000), pour le sélecteur.</li><li><strong><code>/resolve?path=/</code> sert la page d&#39;accueil</strong> comme toute page (<code>kind: page</code>, même ACL, même publication, même <code>seo</code>), avec <code>path</code> = <code>/</code>, une canonique sur la racine et un fil d&#39;Ariane réduit à l&#39;accueil. Dans le fil des autres pages, l&#39;accueil est nommé à <code>/</code>.</li><li><strong>L&#39;adresse propre de la page d&#39;accueil redirige</strong> (redirection décrite 301 vers <code>/</code>), y compris depuis un ancien chemin : une seule adresse pour un seul contenu. Le plan de site et la recherche donnent <code>/</code>.</li><li><strong>La racine d&#39;une autre langue (<code>/en</code>, <code>/en/</code>) répond 404.</strong> Une page n&#39;est servie que dans la langue par défaut de son site (ADR-0034) ; une redirection permanente vers <code>/</code> deviendrait fausse le jour où les pages seront traduites.</li><li><strong>Descripteur public : <code>GET /api/v1/public/site?host=…</code> (ou <code>site_id=…</code>)</strong>, exactement l&#39;un des deux (422 sinon), même résolution d&#39;hôte que <code>/resolve</code> (casse et port ignorés), <strong>404 unique</strong> pour un hôte inconnu. Il rend <code>organization_id</code>, <code>site_id</code>, <code>name</code>, <code>default_locale</code>, <code>locales</code>, <code>locale_segments</code>, <code>home_path</code> (<code>&quot;/&quot;</code> si un anonyme peut lire la page d&#39;accueil, sinon <code>null</code>), <code>home_page_id</code>, <code>indexable</code> et <code>url</code>. Rien de privé (ni courriel, ni mesure d&#39;audience, ni clé, ni réglage interne). En-tête de cache public court, comme <code>/resolve</code>.</li><li><strong>Pas de limite de débit sur le descripteur</strong>, comme <code>/resolve</code> et <code>/files</code> (décision du 30/09/2026, ADR-0035) : il est appelé par le serveur du front à chaque page vue, et une limite par adresse couperait le site à la première affluence. La route est en lecture seule et se met en cache ; le déni de service volumétrique reste l&#39;affaire du proxy (ADR-0045).</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Convention de slug « accueil »</strong> (la page de slug <code>accueil</code> est la page d&#39;accueil)</td><td>Implicite et fragile : renommer le slug change la racine sans qu&#39;on le voie, un site en anglais n&#39;a pas de page « accueil », et une page de même slug ailleurs dans l&#39;arbre serait ambiguë.</td></tr><tr><td><strong>Servir l&#39;accueil à son chemin propre et à <code>/</code></strong></td><td>Deux adresses pour un même contenu : contenu dupliqué pour les moteurs.</td></tr><tr><td><strong>Contrainte en base <code>(site_id, id)</code></strong></td><td>Un index unique de plus sur <code>pages</code> pour un seul lecteur ; le contrôle par le service suffit, et la lecture revérifie.</td></tr><tr><td><strong>Rediriger <code>/en</code> vers <code>/</code></strong></td><td>Deviendrait faux quand les pages seront traduites ; une 301 est mise en cache durablement.</td></tr><tr><td><strong>Limiter le débit du descripteur</strong></td><td>Voir la décision n°7.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Un front ne connaît que son hôte : <code>GET /public/site</code> lui donne tout le reste, et <code>/resolve?path=/</code> sert sa racine.</li><li>Une seule adresse pour la page d&#39;accueil, dans la résolution, le plan de site et la recherche.</li></ul><p><strong>Négatives</strong></p><ul><li>Le chemin propre d&#39;une page d&#39;accueil n&#39;est plus servi : un lien existant vers lui passe par une redirection.</li><li>Le descripteur est une route publique de plus sans limite de débit, à rouvrir avec <code>/resolve</code> et <code>/files</code> si une mesure montre un abus.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Migration 0047 (<code>sites.home_page_id</code>, <code>ON DELETE SET NULL</code>), aller-retour <code>upgrade head</code> / <code>downgrade 0046</code> / <code>upgrade head</code> passé le 01/10/2026.</li><li>[x] Résolution de <code>/</code>, redirection du chemin propre, plan de site et recherche ; route de réglage et descripteur public. Preuve : <code>tests/test_page_d_accueil_et_descripteur.py</code> (15 tests verts) ; sans le changement de <code>public_resolve.py</code>, la racine, la redirection et le plan de site échouent (3 rouges).</li><li>[x] Sélecteur « Page d&#39;accueil » dans <strong>Multi-site › Sites</strong> (<code>components/multisite/SiteHomePageForm.vue</code>, relais <code>server/api/sites/[id]/home-page.*.ts</code>) et paragraphe de la notice (§7.12).</li></ul>',16)])])}const m=t(d,[["render",a]]);export{g as __pageData,m as default};
